/* ---------- Task table ---------- */
/* agent tasks in a sortable table, with bulk actions in the head while rows are picked. The card sits on two columns
   (owner, 18 Nov), its content 16px from every edge: the head's neutral mark in a 28px column with every row's checkbox
   centred under it, and the title, the Task heading and each task's name 12px after it. A row's hover and picked fill is a
   quiet grey that spans the content box, no wider, with round corners (no lines between rows cut through it); the costs,
   the times and their headings sit 8px inside it, and Clear's words end over them. No room is kept: the card grows and
   shrinks with its rows (grow()) and stays centred, and an empty table shows its empty state in their place */
/* its content 16px in from every edge, the last row's fill too, hovered or picked (owner, 21 Nov: "padding is off") */
.ttx{position:relative;width:100%;padding:16px;container:ttx/inline-size;--dm-ttx-r:calc(10px * var(--dm-rk-m,var(--dm-rk)))}
/* the head: the mark, then the title and its summary, or, while rows are picked, what you can do to them */
.ttx-hd{display:flex;align-items:center;gap:12px;padding-bottom:12px;border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.ttx-hi{width:28px;height:28px;display:grid;place-items:center;flex:none;border-radius:var(--dm-r-sm);color:var(--dm-fg2);background:var(--dm-chip)}
.ttx-hx{position:relative;flex:1;min-width:0;height:28px}
.ttx-ti,.ttx-sb{position:absolute;inset:0;display:flex;align-items:center;transition:opacity .28s var(--dm-ease),transform .45s var(--dm-ease),filter .28s var(--dm-ease)}
.ttx-ti{gap:8px;white-space:nowrap}
.ttx-ti b{flex:none;font-size:14px;font-weight:500;line-height:20px}
.ttx-sum{min-width:0;font-size:12.5px;line-height:18px;overflow:hidden;text-overflow:ellipsis}
.ttx-sb{gap:2px;opacity:0;transform:translateY(10px);filter:blur(3px);pointer-events:none}
.ttx.selecting .ttx-ti{opacity:0;transform:translateY(-10px);filter:blur(3px);pointer-events:none}
.ttx.selecting .ttx-sb{opacity:1;transform:none;filter:none;pointer-events:auto}
.ttx-n{margin-right:8px;font-size:13px;font-weight:500;white-space:nowrap}
.ttx-sp{flex:1}
/* Clear's words end over the times, 8px inside the rows' fill, its hover box reaching out round them */
.ttx-sb .ttx-clr{margin-right:-3px}
.ttx-sb .pill.ttx-del{color:var(--dm-bad)}
@media (hover:hover) and (pointer:fine){.ttx-sb .pill.ttx-del:hover{background:color-mix(in srgb,var(--dm-bad) 10%,transparent);color:var(--dm-bad)}}
/* nothing in it grows or shrinks when it is pressed (owner, 18 Nov) */
.ttx :is(.pill,.ib):active{transform:none}
/* the table: the checkbox column under the head's mark, the task's name taking the room that is left (cut short with an
   ellipsis rather than pushing the card wider), and the other columns as wide as their words. Rows stand 2px apart, and
   the headings sit right under the divider, as close as any first line (owner, 18 Nov: no padding added on top) */
.ttx-t{width:100%;margin:-2px 0;border-collapse:separate;border-spacing:0 2px;font-size:13px}
.ttx-t th{height:32px;padding:0 8px;text-align:left;font-weight:500;font-size:12px;color:var(--dm-muted);white-space:nowrap}
.ttx-t td{height:36px;padding:0 8px;white-space:nowrap;transition:background-color .25s var(--dm-ease)}
.ttx-t :is(th,td).ck{width:28px;padding:0}
.ttx-t :is(th,td).ck .ttx-cb{margin:0 6px}
.ttx-t :is(th,td).nm{width:100%;max-width:0;padding-left:12px;overflow:hidden;text-overflow:ellipsis}
.ttx-t :is(th,td).r{text-align:right}
/* it reads as a table of columns (owner, 21 Nov: "there are not vertical lines here again, why?"): a hairline after every column
   from Task to the one before the last, in every style and wherever the columns have been moved, the checkbox staying with
   the task's name. Each cell's line reaches 1px over the 2px between rows, so the lines run unbroken. The columns resize and
   move as in a spreadsheet (cols()); sized by hand, a cell too narrow for its words cuts them short */
.ttx{--dm-ttx-col:color-mix(in srgb,color-mix(in srgb,var(--dm-line),var(--dm-fg) 9%) 50%,transparent)}
.ttx-t :is(th,td):not(.ck){position:relative}
.ttx-t :is(th,td):not(:first-child):not(:last-child)::after{content:"";position:absolute;right:0;top:-1px;bottom:-1px;width:1px;background:var(--dm-ttx-col);pointer-events:none}
.ttx-t.cols-rz td:not(.ck){overflow:hidden;text-overflow:ellipsis}
.ttx-t.cols-rz :is(th,td):is(.ck,.nm){width:auto;max-width:none}
/* columns sized wider than the card scroll sideways inside it, as a spreadsheet's do */
.ttx-sc:has(>.ttx-t.cols-rz){overflow-x:auto}
.ttx-t.cols-rz th .ttx-s{max-width:100%}
/* a header sorts its column: a quiet arrow shows on hover and stays on the column the rows are sorted by. Over a column set
   to the right the arrow goes before the word, so the word ends where the column's figures do */
.ttx-s{display:inline-flex;align-items:center;gap:3px;height:24px;margin:0 -6px;padding:0 6px;border-radius:calc(6px * var(--dm-rk-s,var(--dm-rk)));color:inherit;font:inherit;transition:color .2s,background-color .2s}
.ttx-t th.r .ttx-s{flex-direction:row-reverse}
@media (hover:hover) and (pointer:fine){.ttx-s:hover{color:var(--dm-fg);background:var(--dm-row)}}
.ttx-s .ar{display:grid;opacity:0;transition:opacity .2s,transform .35s var(--dm-ease)}
@media (hover:hover) and (pointer:fine){.ttx-s:hover .ar{opacity:.45}}
.ttx-s.on{color:var(--dm-fg)}
.ttx-s.on .ar{opacity:1}
.ttx-s.on.desc .ar{transform:rotate(180deg)}
/* rows: the shared hover, and a slightly deeper grey while picked, with the fill's corners round at its two ends */
.ttx-t tbody tr[data-id]{cursor:pointer}
.ttx-t tbody tr[data-id]>td:first-child{border-radius:var(--dm-ttx-r) 0 0 var(--dm-ttx-r)}
.ttx-t tbody tr[data-id]>td:last-child{border-radius:0 var(--dm-ttx-r) var(--dm-ttx-r) 0}
@media (hover:hover) and (pointer:fine){.ttx-t tbody tr[data-id]:hover>td{background:var(--dm-row)}}
.ttx-t tbody tr.sel>td{background:color-mix(in srgb,var(--dm-fg) 6%,transparent)}
@media (hover:hover) and (pointer:fine){.ttx-t tbody tr.sel:hover>td{background:color-mix(in srgb,var(--dm-fg) 8%,transparent)}}
.ttx-t td.nm{font-weight:500}
.ttx-t .ag{display:flex;align-items:center;gap:7px;min-width:0;color:var(--dm-fg2)}
/* a long agent name is cut short with an ellipsis rather than running into the time beside it */
.ttx-t .ag>span{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.ttx-t .ag .av{width:20px;height:20px;font-size:9.5px}
.ttx-t td.num{color:var(--dm-fg2)}
.ttx-t td.up{color:var(--dm-muted)}
/* on a picked row's grey the times step up a shade, so they keep 4.5:1 */
.ttx-t tbody tr.sel td.up{color:var(--dm-fg2)}
/* checkboxes: a clear 1.5px edge, and a tick that springs in; select-all shows a dash while only some rows are picked */
.ttx-cb{display:grid;place-items:center;width:16px;height:16px;border-radius:var(--dm-r-tiny,5px);box-shadow:inset 0 0 0 1.5px var(--dm-fg2);color:var(--dm-on-accent,#fff);transition:background-color .2s,box-shadow .2s}
@media (hover:hover) and (pointer:fine){.ttx-cb:hover{box-shadow:inset 0 0 0 1.5px var(--dm-fg)}}
.ttx-cb[aria-checked="true"],.ttx-cb[aria-checked="mixed"]{background:var(--dm-accent);box-shadow:inset 0 0 0 1px var(--dm-accent-mark,var(--dm-accent))}
.ttx-cb svg{grid-area:1/1;width:11px;height:11px;opacity:0;transform:scale(.4);transition:opacity .15s,transform .3s cubic-bezier(.34,1.4,.64,1)}
.ttx-cb[aria-checked="true"] .ck-y,.ttx-cb[aria-checked="mixed"] .ck-m{opacity:1;transform:none}
/* status: the tag's look, its status tint with its words in that hue: Running in the accent, Done green, Failed red, Queued
   and Paused grey. The tint is mixed into the surface, so the chip is opaque and its words keep 4.5:1 and APCA Lc 60 on a
   picked row and in dark mode too */
.ttx-st{--dm-sc:var(--dm-fg2);--dm-sb:var(--dm-chip);display:inline-flex;align-items:center;height:22px;padding:0 9px 0 7px;border-radius:var(--dm-r-tag);font-size:12px;font-weight:500;color:var(--dm-sc);background:color-mix(in srgb,var(--dm-sb) 70%,var(--dm-surface));transition:color .35s var(--dm-ease),background-color .35s var(--dm-ease)}
@supports (corner-shape:squircle){.ttx-st{border-radius:var(--dm-r-tag-sq)}}
.ttx-st .sv{display:inline-flex;align-items:center;gap:6px}
/* running reads in the accent's text colour on a tint of its mark, so a light accent like lime stays legible */
.ttx-st[data-s="run"]{--dm-sc:var(--dm-accent-fg,var(--dm-accent));--dm-sb:var(--dm-accent-bg)}
.ttx-st[data-s="done"]{--dm-sc:var(--dm-ok);--dm-sb:var(--dm-ok-bg)}
.ttx-st[data-s="fail"]{--dm-sc:var(--dm-bad);--dm-sb:var(--dm-bad-bg)}
.ttx-st .spin{width:10px;height:10px}
.ttx-st .i{width:12px;height:12px}
/* a new status fades in out of a blur; a cancelled row slides away before it goes */
.ttx-sin{animation:ttxsin .32s var(--dm-ease)}
@keyframes ttxsin{from{opacity:0;filter:blur(3px)}}
.ttx-t tbody tr.ttx-out{opacity:0;transform:translateX(14px);transition:opacity .24s var(--dm-ease),transform .24s var(--dm-ease)}
/* when every task is gone: a small sketch of the table on a card, what happened, and a way to bring them back. Soft's
   sketch is a soft card with three rows, the first one's box in the accent's tint; Blueprint keeps its mark */
.ttx-t tbody tr.ttx-empty td{height:auto;max-width:none;padding:24px 16px 26px;text-align:center;white-space:normal}
.ttx.none .ttx-t thead{display:none}
.ttx-sum:empty{display:none}
.ttx-em{display:flex;flex-direction:column;align-items:center;gap:4px}
.ttx-em .ic{display:none;place-items:center;width:36px;height:36px;margin-bottom:8px;border-radius:var(--dm-r-in);background:var(--dm-chip);color:var(--dm-muted)}
.ttx-em b{font-size:13.5px;line-height:18px;font-weight:500}
.ttx-em>span:not(.ic,.ttx-em-art){max-width:290px;font-size:12.5px;line-height:1.5;color:var(--dm-muted)}
.ttx-em .pill{margin-top:12px}
.ttx-em-art{flex:none;display:flex;flex-direction:column;justify-content:center;gap:7px;width:84px;height:56px;margin-bottom:12px;padding:0 12px;border-radius:calc(9px * var(--dm-rk));background:var(--dm-surface);box-shadow:var(--dm-shadow)}
.ttx-em-art .r{display:flex;align-items:center;gap:6px}
.ttx-em-art i{display:block;flex:none;height:4px;border-radius:calc(2px * var(--dm-rk));background:color-mix(in srgb,var(--dm-fg) 9%,var(--dm-surface))}
.ttx-em-art .t{width:8px;height:8px;border-radius:calc(2.5px * var(--dm-rk))}
.ttx-em-art .l{width:36px}
.ttx-em-art .r:nth-child(2) .l{width:30px}
.ttx-em-art .r:nth-child(3) i{background:color-mix(in srgb,var(--dm-fg) 5%,var(--dm-surface))}
.ttx-em-art .r:nth-child(3) .l{width:24px}
.ttx-em-art .r:first-child .t{background:var(--dm-accent-bg)}
.ttx-em-art .r:first-child .l{background:color-mix(in srgb,var(--dm-accent-mark,var(--dm-accent)) 55%,var(--dm-surface))}
:root:not([data-style="soft"],[data-style="clean"]) .ttx-em .ic:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){display:grid}
:root:not([data-style="soft"],[data-style="clean"]) .ttx-em-art:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){display:none}
/* narrow, on a phone or in a narrow card: each task stacks, its name and cost on top and its status, agent and last update
   on a line under it, on the same columns (its checkbox under the head's mark, its words where the title's start); the
   header row keeps select all and the sort buttons, and the bulk actions stay in the head above. The container is the card,
   inside its 16px padding, so this is a card under 560px wide */
@container ttx (max-width:528px){
  .ttx-t{display:block;margin:0}
  .ttx-t thead,.ttx-t tbody{display:flex;flex-direction:column;gap:2px}
  /* each task is a small grid: its name and cost on the first line, and its status, agent and last update on the second,
     the status in a column of its own so the agents line up from row to row; the headings sit in the same places, so each
     sort button is over what it sorts */
  .ttx-t tr{position:relative;display:grid;grid-template-columns:80px minmax(0,1fr) auto;gap:4px 10px;align-items:center;padding:8px 8px 8px 40px;border-radius:var(--dm-ttx-r);transition:background-color .25s var(--dm-ease)}
  .ttx-t thead tr{padding-top:4px;padding-bottom:4px}
  .ttx-t th,.ttx-t td,.ttx-t :is(th,td).nm{display:block;width:auto;max-width:none;height:auto;padding:0}
  .ttx-t :is(th,td).ck{position:absolute;left:6px;top:10px;width:auto}
  .ttx-t :is(th,td).ck .ttx-cb{margin:0}
  /* select all sits on the headings' first line, as each row's box sits on its name's */
  .ttx-t thead th.ck{top:8px}
  .ttx-t :is(th,td).nm{grid-area:1/1/2/3;min-width:0}
  .ttx-t td.nm{white-space:normal;line-height:20px}
  .ttx-t :is(th,td):nth-child(5){grid-area:1/3}
  .ttx-t :is(th,td):nth-child(3){grid-area:2/1}
  .ttx-t :is(th,td):nth-child(4){grid-area:2/2;min-width:0}
  .ttx-t :is(th,td):nth-child(6){grid-area:2/3}
  .ttx-t td:is(:nth-child(5),.up),.ttx-t .ag{font-size:12px}
  .ttx-s:not(.on) .ar{display:none}
  .ttx-t tbody tr[data-id]>td:is(:first-child,:last-child){border-radius:0}
  .ttx-t tbody tr.sel>td{background:none}
  @media (hover:hover) and (pointer:fine){.ttx-t tbody tr[data-id]:hover>td,.ttx-t tbody tr.sel:hover>td{background:none}}
  @media (hover:hover) and (pointer:fine){.ttx-t tbody tr[data-id]:hover{background:var(--dm-row)}}
  .ttx-t tbody tr.sel{background:color-mix(in srgb,var(--dm-fg) 6%,transparent)}
  @media (hover:hover) and (pointer:fine){.ttx-t tbody tr.sel:hover{background:color-mix(in srgb,var(--dm-fg) 8%,transparent)}}
  .ttx-t tbody tr.ttx-empty{display:block;padding:0}
  .ttx-t tbody tr.ttx-empty td{padding:24px 16px 26px}
  /* as cards, the tasks have no columns to draw, size or move */
  .ttx-t :is(th,td)::after,.ttx-t .col-rz{display:none}
}
/* a phone: the head's mark is a 24px tile with the words 8px after it, the same columns run down the card, and the bulk
   actions drop their icons */
@container ttx (max-width:388px){
  .ttx-hd{gap:8px}.ttx-hi{width:24px;height:24px;border-radius:var(--dm-r-xs,6px)}
  .ttx-t tr{padding-left:32px}.ttx-t :is(th,td).ck{left:4px}
  .ttx-sb .pill{padding:0 7px}.ttx-sb .pill .i{display:none}.ttx-n{margin-right:2px}
  .ttx-sb .ttx-clr{margin-right:1px}
}
/* Clean (owner, 18 Nov): the head's mark has a hairline like the other tiles; checkboxes are white rounded squares with a
   clear edge and a soft inner shadow, ink once ticked (they are controls); the head's swap fades without a blur; the empty
   state is Clean's (lab/clean): a sketch of the table's rows on a small white card, the title, one muted line and an
   outline button */
:root[data-style="clean"] .ttx-hi,:root [data-style="clean"] .ttx-hi,:root [data-style="clean"].ttx-hi{box-shadow:inset 0 0 0 1px var(--dm-hair)}
/* no red fill behind an error (owner, 17 Nov): Failed keeps its red words and mark on the neutral chip */
:root[data-style="clean"] .ttx-st[data-s="fail"],:root [data-style="clean"] .ttx-st[data-s="fail"],:root [data-style="clean"].ttx-st[data-s="fail"]{--dm-sb:var(--dm-chip)}
:root[data-style="clean"] .ttx-ti,:root [data-style="clean"] .ttx-ti,:root [data-style="clean"].ttx-ti,:root[data-style="clean"] .ttx-sb,:root [data-style="clean"] .ttx-sb,:root [data-style="clean"].ttx-sb{transition:opacity var(--dm-t-fast) var(--dm-ease),transform var(--dm-t) var(--dm-ease)}
:root[data-style="clean"] :is(.ttx-sb,.ttx.selecting .ttx-ti),:root [data-style="clean"] :is(.ttx-sb,.ttx.selecting .ttx-ti),:root [data-style="clean"]:is(.ttx-sb,.ttx.selecting .ttx-ti){filter:none}
:root[data-style="clean"] .ttx-sb,:root [data-style="clean"] .ttx-sb,:root [data-style="clean"].ttx-sb{transform:translateY(6px)}
:root[data-style="clean"] .ttx.selecting .ttx-ti,:root [data-style="clean"] .ttx.selecting .ttx-ti,:root [data-style="clean"].ttx.selecting .ttx-ti{transform:translateY(-6px)}
:root[data-style="clean"] .ttx.selecting .ttx-sb,:root [data-style="clean"] .ttx.selecting .ttx-sb,:root [data-style="clean"].ttx.selecting .ttx-sb{transform:none}
:root[data-style="clean"] .ttx-t td,:root [data-style="clean"] .ttx-t td,:root [data-style="clean"].ttx-t td{transition:background-color var(--dm-t-fast) var(--dm-ease)}
:root[data-style="clean"] .ttx-s,:root [data-style="clean"] .ttx-s,:root [data-style="clean"].ttx-s{transition:color var(--dm-t-fast) var(--dm-ease),background-color var(--dm-t-fast) var(--dm-ease)}
:root[data-style="clean"] .ttx-cb,:root [data-style="clean"] .ttx-cb,:root [data-style="clean"].ttx-cb{border-radius:5px;background:var(--dm-surface);box-shadow:inset 0 0 0 1.5px var(--dm-fg2),var(--dm-track-ring);transition:background var(--dm-t-fast) var(--dm-ease),box-shadow var(--dm-t-fast) var(--dm-ease)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .ttx-cb:hover,:root [data-style="clean"] .ttx-cb:hover,:root [data-style="clean"].ttx-cb:hover{box-shadow:inset 0 0 0 1.5px var(--dm-fg),var(--dm-track-ring)}}
:root[data-style="clean"] .ttx-cb:is([aria-checked="true"],[aria-checked="mixed"]),:root [data-style="clean"] .ttx-cb:is([aria-checked="true"],[aria-checked="mixed"]),:root [data-style="clean"].ttx-cb:is([aria-checked="true"],[aria-checked="mixed"]){background:linear-gradient(180deg,var(--dm-btn-1),var(--dm-btn-2));box-shadow:inset 0 0 0 1px var(--dm-btn-2),inset 0 2px 3px -1px rgba(255,255,255,.28);color:var(--dm-on-btn)}
:root[data-style="clean"] .ttx-t tbody tr.ttx-empty td,:root [data-style="clean"] .ttx-t tbody tr.ttx-empty td,:root [data-style="clean"].ttx-t tbody tr.ttx-empty td{padding:28px 16px 30px}
:root[data-style="clean"] .ttx-em-art,:root [data-style="clean"] .ttx-em-art,:root [data-style="clean"].ttx-em-art{justify-content:flex-start;gap:6px;width:136px;height:70px;margin-bottom:16px;padding:14px;border-radius:calc(10px * var(--dm-rk-l,var(--dm-rk)))}
:root[data-style="clean"] .ttx-em-art .r,:root [data-style="clean"] .ttx-em-art .r,:root [data-style="clean"].ttx-em-art .r{gap:8px;height:10px}
:root[data-style="clean"] .ttx-em-art .r>i,:root [data-style="clean"] .ttx-em-art .r>i,:root [data-style="clean"].ttx-em-art .r>i{height:6px;border-radius:3px;background:var(--dm-ghost)}
:root[data-style="clean"] .ttx-em-art .r>.t,:root [data-style="clean"] .ttx-em-art .r>.t,:root [data-style="clean"].ttx-em-art .r>.t{width:10px;height:10px}
:root[data-style="clean"] .ttx-em-art .r>.l,:root [data-style="clean"] .ttx-em-art .r>.l,:root [data-style="clean"].ttx-em-art .r>.l{width:58px}
:root[data-style="clean"] .ttx-em-art .r:nth-child(3)>i,:root [data-style="clean"] .ttx-em-art .r:nth-child(3)>i,:root [data-style="clean"].ttx-em-art .r:nth-child(3)>i{background:var(--dm-ghost-2)}
:root[data-style="clean"] .ttx-em .pill,:root [data-style="clean"] .ttx-em .pill,:root [data-style="clean"].ttx-em .pill{color:var(--dm-fg);background:linear-gradient(180deg,var(--dm-btn2-1),var(--dm-btn2-2));box-shadow:var(--dm-btn2-depth)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .ttx-em .pill:hover,:root [data-style="clean"] .ttx-em .pill:hover,:root [data-style="clean"].ttx-em .pill:hover{box-shadow:var(--dm-btn2-hover)}}
:root[data-style="clean"] .ttx-em .pill:active,:root [data-style="clean"] .ttx-em .pill:active,:root [data-style="clean"].ttx-em .pill:active{box-shadow:var(--dm-btn2-press)}
/* Clean reads as a ruled table (owner, 22 Nov: "more prominent", "horizontal lines"): the head is Clean's off-white strip
   over a hairline, the table starts 8px under it, and a half-strength hairline runs under the headings and between the
   rows, in the columns' grey. The rows stand edge to edge with square ends, so the lines run unbroken; a row's hover and
   picked fill is the same quiet grey between its lines. Soft and Blueprint keep their unruled rows with round fills */
